style.css:
@-moz-document domain("www.cba.pl") {
/* Główne tła */
  html,
  body,
  #layout,
  #mainscreen,
  #mailview,
  #mailview-left,
  #mailview-right,
  #mailview-bottom,
  #messagecontent,
  #messagebody,
  #messageheader,
  #messagepartcontainer,
  #messagepreview,
  #messageframe,
  #messagecontframe,
  .iframe,
  .boxcontent,
  .uibox,
  .listbox,
  .scroller,
  .pagenav {
    background: #121212 !important;
    background-color: #121212 !important;
    color: #e6e6e6 !important;
    border-color: #333 !important;
  }

  /* Treść wiadomości */
  body#messagebody,
  body.rcmBody,
  .rcmBody,
  .rcmBody *,
  .message-part,
  .message-part *,
  .message-htmlpart,
  .message-htmlpart *,
  .message-textpart,
  .message-textpart *,
  #message-htmlpart1,
  #message-htmlpart1 *,
  #message-htmlpart2,
  #message-htmlpart2 *,
  #message-htmlpart3,
  #message-htmlpart3 *,
  .partheader,
  .partcontent {
    background: #121212 !important;
    background-color: #121212 !important;
    color: #e6e6e6 !important;
    border-color: #333 !important;
  }

  /* Bardzo ważne dla maili HTML */
  table,
  tbody,
  thead,
  tfoot,
  tr,
  td,
  th,
  div,
  p,
  span,
  font,
  center,
  blockquote {
    background-color: transparent !important;
    color: #e6e6e6 !important;
    border-color: #333 !important;
  }

  /* Linki */
  a,
  a:visited {
    color: #8ab4f8 !important;
  }

  a:hover {
    color: #aecbfa !important;
  }

  /* Formularze */
  input,
  textarea,
  select,
  button {
    background: #202124 !important;
    color: #ffffff !important;
    border: 1px solid #444 !important;
  }

  /* Lista wiadomości */
  #messagelist,
  #messagelist table,
  #messagelist tr,
  #messagelist td,
  #messagelist th,
  .messagelist,
  .messagelist tr,
  .messagelist td,
  .listing,
  .listing tr,
  .listing td,
  .listing th {
    background: #181818 !important;
    color: #e6e6e6 !important;
    border-color: #333 !important;
  }

  #messagelist tr.selected td,
  .messagelist tr.selected td,
  .listing tr.selected td {
    background: #2b3a55 !important;
    color: #ffffff !important;
  }

  /* Lewy pasek folderów */
  #mailboxlist,
  #mailboxlist *,
  #folderlist,
  #folderlist * {
    background-color: #121212 !important;
    color: #e6e6e6 !important;
    border-color: #333 !important;
  }

  #mailboxlist li.selected,
  #mailboxlist li.selected a,
  #folderlist li.selected,
  #folderlist li.selected a {
    background-color: #2b3a55 !important;
    color: #ffffff !important;
  }

  /* Górne paski */
  #topline,
  #taskbar,
  #toolbar,
  #quicksearchbar,
  .toolbar,
  .boxtitle,
  .header {
    background: #1e1e1e !important;
    color: #f0f0f0 !important;
    border-color: #333 !important;
  }
}

@-moz-document url-prefix("https://www.cba.pl/roundcubemail/") {
html,
  body,
  body#messagebody,
  body.rcmBody,
  .rcmBody,
  .rcmBody *,
  #messagebody,
  #messagebody *,
  .message-htmlpart,
  .message-htmlpart *,
  .message-part,
  .message-part *,
  table,
  tbody,
  tr,
  td,
  th,
  div,
  p,
  span,
  font,
  blockquote {
    background: #121212 !important;
    background-color: #121212 !important;
    color: #e6e6e6 !important;
    border-color: #333 !important;
  }

  a {
    color: #8ab4f8 !important;
  }
}
